const t={maxFlow:{intro:{t:0,b:{t:2,i:[{t:3}],s:"找出你的熱端能持續輸出的最高體積流量（mm³/s）——做法是逐步拉高流量，同時觀察擠出機的 StallGuard 負載，捕捉齒輪打滑的瞬間。請先預覽測試計畫；實機測試會加熱並擠出料，執行前請先準備好印表機。"}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"說明"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"關於最大流量"}},close:{t:0,b:{t:2,i:[{t:3}],s:"關閉"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"使用方式"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"設定測試溫度與耗材直徑（選一個熱端可自動帶入）。"}},{t:0,b:{t:2,i:[{t:3}],s:"預覽計畫——它會列出每個流量步階以及各步推送多少料。"}},{t:0,b:{t:2,i:[{t:3}],s:"勾選安全檢查清單，接著執行實機測試（會加熱＋擠出料）。"}},{t:0,b:{t:2,i:[{t:3}],s:"讀取最高持續流量，並複製建議的切片軟體數值。"}}],topics:{howItWorks:{title:{t:0,b:{t:2,i:[{t:3}],s:"測試原理"}},body:{t:0,b:{t:2,i:[{t:3}],s:"擠出機以穩定遞增的體積流量推送耗材。當滾花齒輪夾得牢時，StallGuard 負載讀值保持平穩；一旦開始打滑，讀值就會劇烈跳動。打滑前所達到的最高流量，就是你能持續輸出的最大流量。一偵測到打滑就會停止拉升，因此不會在第一次打滑後繼續磨耗耗材。"}}},stallguard:{title:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard 打滑偵測"}},body:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard 是 TMC 驅動的一項功能，會回報馬達負載。本測試在每個流量步階多次取樣，並尋找離散度（IQR）或變異（CV）的突然升高——這正是齒輪失去抓力的特徵。閾值來自每個驅動的設定檔。注意：在 TMC2209 擠出機上會使用實驗性的 SG4 路徑，因此請把第一次執行視為校正。"}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"安全"}},body:{t:0,b:{t:2,i:[{t:3}],s:"這是一項會發熱且有動作的測試，並刻意讓擠出機打滑。請裝好耗材、確保噴嘴下方淨空（在熱床或廢料區上方），並全程在旁看顧。印表機列印中時會拒絕執行，測試結束時加熱器一律會關閉。"}}},slicer:{title:{t:0,b:{t:2,i:[{t:3}],s:"套用結果"}},body:{t:0,b:{t:2,i:[{t:3}],s:"把建議值填入切片軟體的「最大體積速度」（依耗材設定）。保守值（測得上限的 80%）是日常安全上限；平衡值（90%）可再多推一點。提高熱端溫度通常能拉高可達成的流量。"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"詞彙表"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{flow:{term:{t:0,b:{t:2,i:[{t:3}],s:"體積流量"}},def:{t:0,b:{t:2,i:[{t:3}],s:"熱端每秒能熔化多少塑料（mm³/s）——高速列印真正的速度上限。"}}},stallguard:{term:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},def:{t:0,b:{t:2,i:[{t:3}],s:"TMC 驅動的一個訊號，回報馬達機械負載，此處用來感測擠出機打滑。"}}},slip:{term:{t:0,b:{t:2,i:[{t:3}],s:"打滑"}},def:{t:0,b:{t:2,i:[{t:3}],s:"擠出機齒輪再也跟不上、無法及時夾住耗材而空轉——即流量天花板。"}}},meltzone:{term:{t:0,b:{t:2,i:[{t:3}],s:"熔融區"}},def:{t:0,b:{t:2,i:[{t:3}],s:"熱端的加熱長度；熔融區較長（例如 Volcano）能維持更高流量。"}}}}},params:{title:{t:0,b:{t:2,i:[{t:3}],s:"測試參數"}},temperature:{t:0,b:{t:2,i:[{t:3}],s:"溫度（°C）"}},filamentDiameter:{t:0,b:{t:2,i:[{t:3}],s:"耗材直徑 Ø（mm）"}},hotend:{t:0,b:{t:2,i:[{t:3}],s:"熱端（選填）"}},hotendNone:{t:0,b:{t:2,i:[{t:3}],s:"- 無 -"}},hotendHint:{t:0,b:{t:2,i:[{t:3,v:"預期約 "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},startFlow:{t:0,b:{t:2,i:[{t:3}],s:"起始流量（mm³/s）"}},endFlow:{t:0,b:{t:2,i:[{t:3}],s:"結束流量（mm³/s）"}},stepFlow:{t:0,b:{t:2,i:[{t:3}],s:"步階（mm³/s）"}},samples:{t:0,b:{t:2,i:[{t:3}],s:"每步取樣數"}},extrudePerStep:{t:0,b:{t:2,i:[{t:3}],s:"每步擠出量（mm）"}},driver:{t:0,b:{t:2,i:[{t:3}],s:"擠出機驅動"}},driverDetected:{t:0,b:{t:2,i:[{t:3}],s:"自印表機偵測"}},autoStealthchop:{t:0,b:{t:2,i:[{t:3}],s:"測試時自動啟用 StealthChop"}},autoStealthchopHint:{t:0,b:{t:2,i:[{t:3}],s:"僅限 TMC2209/2240：暫時對擠出機寫入 stealthchop_threshold，讓 StallGuard 能讀取，測試後再將其註解掉。會還原 printer.cfg；前後各需一次韌體重啟。"}},method:{t:0,b:{t:2,i:[{t:3}],s:"偵測方式"}},methodHint:{t:0,b:{t:2,i:[{t:3}],s:"自動使用 StallGuard，當 StallGuard 無法讀取時改用工具頭加速度計（振動）。加速度計方式為實驗性。"}}},method:{auto:{t:0,b:{t:2,i:[{t:3}],s:"自動"}},stallguard:{t:0,b:{t:2,i:[{t:3}],s:"StallGuard"}},accel:{t:0,b:{t:2,i:[{t:3}],s:"加速度計"}}},plan:{button:{t:0,b:{t:2,i:[{t:3}],s:"預覽計畫"}},title:{t:0,b:{t:2,i:[{t:3}],s:"計畫的流量爬升"}},stepCount:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" 個步階"}]}},totalExtrude:{t:0,b:{t:2,i:[{t:4,k:"mm"},{t:3,v:" mm 耗材"}]}},sgField:{t:0,b:{t:2,i:[{t:3,v:"StallGuard 欄位："},{t:4,k:"field"}]}},sgFieldUnknown:{t:0,b:{t:2,i:[{t:3}],s:"此驅動沒有已知的 StallGuard 欄位"}},flowHead:{t:0,b:{t:2,i:[{t:3}],s:"流量（mm³/s）"}},feedrateHead:{t:0,b:{t:2,i:[{t:3}],s:"進給速度（mm/min）"}},warning:{t:0,b:{t:2,i:[{t:3}],s:"實機測試會加熱熱端並擠出耗材，並刻意推到打滑為止。此處僅為預覽——尚未執行任何動作。"}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"執行前——安全檢查清單"}},items:[{t:0,b:{t:2,i:[{t:3}],s:"耗材已裝好且進料順暢。"}},{t:0,b:{t:2,i:[{t:3}],s:"噴嘴下方淨空——在熱床或廢料桶上方，而非懸空對著工件。"}},{t:0,b:{t:2,i:[{t:3}],s:"我接受這會刻意磨耗／打滑部分耗材。"}},{t:0,b:{t:2,i:[{t:3}],s:"我會在整個測試期間留在印表機旁。"}}],ack:{t:0,b:{t:2,i:[{t:3}],s:"上述事項我都已完成，印表機已就緒"}},note:{t:0,b:{t:2,i:[{t:3}],s:"列印中時會拒絕執行；結束時加熱器會自動關閉。"}}},run:{button:{t:0,b:{t:2,i:[{t:3}],s:"執行實機測試"}},running:{t:0,b:{t:2,i:[{t:3}],s:"執行中…（加熱＋擠出）"}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:"開始實機最大流量測試？"}},confirmBody:{t:0,b:{t:2,i:[{t:3,v:"這會把熱端加熱到 "},{t:4,k:"temp"},{t:3,v:" °C，並擠出最多 "},{t:4,k:"mm"},{t:3,v:" mm 的耗材，持續拉升直到擠出機打滑。"}]}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"立即執行"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"取消"}},busy:{t:0,b:{t:2,i:[{t:3}],s:"已拒絕：印表機忙碌中（列印或暫停）。閒置後請再試。"}},error:{t:0,b:{t:2,i:[{t:3}],s:"測試失敗。"}},noSg:{t:0,b:{t:2,i:[{t:3}],s:"未讀取到任何 StallGuard 取樣——打滑結果可能不可靠。此型號的驅動即時 SG 欄位可能需要調整。"}},progress:{t:0,b:{t:2,i:[{t:3,v:"步階 "},{t:4,k:"step"},{t:3,v:"/"},{t:4,k:"total"},{t:3,v:" - "},{t:4,k:"flow"},{t:3,v:" mm³/s"}]}},starting:{t:0,b:{t:2,i:[{t:3}],s:"加熱／啟動中…"}},abort:{t:0,b:{t:2,i:[{t:3}],s:"中止執行"}},cancelling:{t:0,b:{t:2,i:[{t:3}],s:"中止中…"}},cancelled:{t:0,b:{t:2,i:[{t:3}],s:"執行已中止——加熱器已關閉。"}},reattached:{t:0,b:{t:2,i:[{t:3}],s:"已重新接上：此結果在頁面離開期間已完成。"}},failed:{t:0,b:{t:2,i:[{t:3}],s:"最大流量執行失敗。"}},abortNote:{t:0,b:{t:2,i:[{t:3}],s:"中止一律會關閉加熱器。"}},parkNote:{t:0,b:{t:2,i:[{t:3}],s:"加熱前，印表機會（必要時）歸位並把噴嘴置中，以利清楚觀察。"}},phase:{enabling:{t:0,b:{t:2,i:[{t:3}],s:"正在啟用 StealthChop…"}},homing:{t:0,b:{t:2,i:[{t:3}],s:"正在歸位印表機…"}},centering:{t:0,b:{t:2,i:[{t:3}],s:"正在置中噴嘴…"}},heating:{t:0,b:{t:2,i:[{t:3}],s:"正在加熱熱端…"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"正在檢查 StallGuard 訊號…"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"正在拉升流量…"}},reverting:{t:0,b:{t:2,i:[{t:3}],s:"正在還原設定…"}}},step:{home:{t:0,b:{t:2,i:[{t:3}],s:"歸位"}},center:{t:0,b:{t:2,i:[{t:3}],s:"置中"}},heat:{t:0,b:{t:2,i:[{t:3}],s:"加熱"}},check:{t:0,b:{t:2,i:[{t:3}],s:"檢查"}},ramp:{t:0,b:{t:2,i:[{t:3}],s:"拉升"}}}},camera:{title:{t:0,b:{t:2,i:[{t:3}],s:"即時攝影機"}},live:{t:0,b:{t:2,i:[{t:3}],s:"LIVE"}},error:{t:0,b:{t:2,i:[{t:3}],s:"攝影機無法使用。"}},willShow:{t:0,b:{t:2,i:[{t:3}],s:"測試期間會以即時攝影機畫面顯示噴嘴。"}},minimize:{t:0,b:{t:2,i:[{t:3}],s:"縮到最小"}},maximize:{t:0,b:{t:2,i:[{t:3}],s:"放到最大"}},enlarge:{t:0,b:{t:2,i:[{t:3}],s:"放大"}},shrink:{t:0,b:{t:2,i:[{t:3}],s:"縮小"}}},result:{title:{t:0,b:{t:2,i:[{t:3}],s:"結果"}},maxFlow:{t:0,b:{t:2,i:[{t:3}],s:"最高持續流量"}},slipAt:{t:0,b:{t:2,i:[{t:3,v:"於 "},{t:4,k:"flow"},{t:3,v:" mm³/s 偵測到打滑"}]}},noSlip:{t:0,b:{t:2,i:[{t:3}],s:"在測試的最高流量內均未打滑"}},reason:{t:0,b:{t:2,i:[{t:3}],s:"詳情"}},recommendTitle:{t:0,b:{t:2,i:[{t:3}],s:"建議的切片軟體數值（最大體積速度）"}},conservative:{t:0,b:{t:2,i:[{t:3}],s:"保守（80%）"}},balanced:{t:0,b:{t:2,i:[{t:3}],s:"平衡（90%）"}},units:{t:0,b:{t:2,i:[{t:3}],s:"mm³/s"}},fromBefore:{t:0,b:{t:2,i:[{t:3,v:"稍早測得（"},{t:4,k:"at"},{t:3,v:"）——再次執行以取得最新數值。"}]}},unreliableTitle:{t:0,b:{t:2,i:[{t:3}],s:"不可靠——無 StallGuard 訊號"}},unmeasured:{t:0,b:{t:2,i:[{t:3}],s:"已達到，但未確認"}},via:{t:0,b:{t:2,i:[{t:3,v:"透過 "},{t:4,k:"method"},{t:3,v:" 測得"}]}},accelExperimental:{t:0,b:{t:2,i:[{t:3}],s:"以振動（加速度計）測得——實驗性；請把此數值當作參考，而非精確上限。"}}},states:{loadingHotends:{t:0,b:{t:2,i:[{t:3}],s:"正在載入熱端…"}}}}};export{t as default};
